 ('notifications','titulo','UPDATE'),('notifications','mensaje','UPDATE'),('notifications','scheduled_at','UPDATE'),('notifications','created_at','UPDATE'),('notifications','read_at','UPDATE'),
 ('practice_slots','cohort_id','INSERT'),('practice_slots','instructor_id','INSERT'),('practice_slots','student_id','INSERT'),('practice_slots','scheduled_at','INSERT'),('practice_slots','duration_minutes','INSERT'),('practice_slots','status','INSERT'),
