 ('enrollments','reprogramaciones_usadas','UPDATE')) v(tab,col,priv) loop
 if not has_column_privilege('service_role','public.'||r.tab,r.col,r.priv) then raise exception 'VERIFICACION_092: falta % en %.%',r.priv,r.tab,r.col;end if;
 end loop;end $columns$;
